static std::vector<std::string> split(const std::string&s){std::vector<std::string>out;size_t a=0;for(size_t j=0;j<=s.size();j++)if(j==s.size()||s[j]==','){out.push_back(s.substr(a,j-a));a=j+1;}return out;}
